#!/usr/bin/env bash
set -euo pipefail
TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT
if printf 'Zg==' | base64 -d >/dev/null 2>&1; then
  _frp_b64d() { base64 -d; }
elif printf 'Zg==' | base64 -D >/dev/null 2>&1; then
  _frp_b64d() { base64 -D; }
else
  _frp_b64d() { python3 -c 'import base64,sys; sys.stdout.buffer.write(base64.b64decode(sys.stdin.buffer.read()))'; }
fi
